"use strict";exports.canToggleArchive=function(t){return!!t&&("AA"===t.type&&"OWNER"===t.role)},exports.centsToYuan=function(t){return((Number(t)||0)/100).toFixed(2)},exports.evenSharesByUser=function(t,r){const e=Array.isArray(r)?r:[],n=function(t,r){if(r<=0||t<0)return[];const e=Math.floor(t/r),n=t-e*r,o=[];for(let u=0;u<r;u++)o.push(e+(u<n?1:0));return o}(t,e.length),o={};return e.forEach((t,r)=>{o[t]=n[r]||0}),o},exports.isUnsettledArchiveError=function(t){return!(!t||"AA_LEDGER_UNSETTLED"!==t.code)},exports.isValidCustomSplit=function(t,r){const e=Array.isArray(r)?r:Object.values(r||{});let n=0;for(const o of e){const t=Number(o);if(!Number.isFinite(t)||t<0)return!1;n+=t}return n===t},exports.payerImpact=function(t,r){const e=Math.max(0,Number(t)||0),n=Math.max(0,Number(r)||0);return{accountDeductCents:e,myConsumptionCents:n,lentCents:Math.max(0,e-n)}},exports.toCents=function(t){const r="number"==typeof t?t:Number(t);return Number.isFinite(r)?Math.round(100*r):0};
